/// <reference types="@cloudflare/workers-types" />
/**
 * Production Cloudflare Worker entry point.
 *
 * OpenNext generates the Next.js fetch worker at build time. This wrapper
 * preserves that handler and adds Cloudflare Cron + Queue event handlers.
 */

// @ts-ignore .open-next/worker.js is generated by opennextjs-cloudflare build.
import openNextWorker, {
  DOQueueHandler,
  DOShardedTagCache,
} from "../.open-next/worker.js";

import {
  claimDueJobs,
  isClaimedAgentJobEnvelope,
  processJob,
  reconcileStaleJobs,
} from "@/lib/jobs/runner";
import { enqueueAutonomousCycles } from "@/lib/jobs/intelligence";
import { dispatchPendingNotifications } from "@/lib/notifications/dispatcher";
import type { AgentJob } from "@/types/database";

// Preserve OpenNext's Durable Object exports when its generated worker uses them.
export { DOQueueHandler, DOShardedTagCache };

interface CloudflareBindings {
  AGENT_JOBS_QUEUE: Queue<AgentJob>;
  BROWSER: {
    quickAction(
      action: "screenshot",
      options: { url: string; viewport?: { width: number; height: number } }
    ): Promise<Response>;
  };
}

export default {
  /**
   * All HTTP requests must pass through OpenNext's generated handler.
   * Do not use a globalThis fallback: that silently serves a fake 200 response
   * and can make a broken production deployment look healthy.
   */
  fetch(
    request: Request,
    env: CloudflareBindings,
    ctx: ExecutionContext
  ): Promise<Response> {
    return openNextWorker.fetch(request, env, ctx);
  },

  /** Queue consumer: process only valid, atomically claimed job envelopes. */
  async queue(
    batch: MessageBatch<unknown>,
    env: CloudflareBindings
  ): Promise<void> {
    for (const message of batch.messages) {
      if (!isClaimedAgentJobEnvelope(message.body)) {
        console.error("[worker-queue] Discarded invalid claimed-job envelope.");
        message.ack();
        continue;
      }

      const job: AgentJob = message.body;
      try {
        const result = await processJob(job, undefined, { browser: env.BROWSER });
        if (result.success || !result.retryable) {
          message.ack();
        } else {
          message.retry();
        }
      } catch (error) {
        console.error("[worker-queue] Job processing failed:", {
          jobId: job.id,
          error: error instanceof Error ? error.message : "Unknown error",
        });
        message.retry();
      }
    }
  },

  /**
   * One account-level Cron trigger runs every minute. The scheduled timestamp
   * gates autonomous cycles to five-minute UTC boundaries without consuming a
   * second Cloudflare Cron trigger.
   */
  async scheduled(
    controller: ScheduledController,
    env: CloudflareBindings,
    ctx: ExecutionContext
  ): Promise<void> {
    ctx.waitUntil(
      dispatchPendingNotifications(50).catch((error) => {
        console.error("[worker-notifications] Delivery pass failed:", error);
      })
    );

    ctx.waitUntil(
      (async () => {
        try {
          try {
            const reconciled = await reconcileStaleJobs();
            if (reconciled > 0) {
              console.warn(`[worker-scheduled] Reconciled ${reconciled} stale agent jobs.`);
            }
          } catch (error) {
            console.error("[worker-scheduled] Stale-job reconciliation failed:", error);
          }

          const scheduledMinute = new Date(controller.scheduledTime).getUTCMinutes();
          if (scheduledMinute % 5 === 0) {
            try {
              const cycles = await enqueueAutonomousCycles();
              if (cycles.queued > 0) {
                console.info(`[worker-scheduled] Enqueued ${cycles.queued} autonomous cycles.`);
              }
            } catch (error) {
              console.error("[worker-scheduled] Autonomous-cycle enqueue failed:", error);
            }
          }

          const dueJobs = await claimDueJobs({ limit: 10, leaseMinutes: 15 });

          for (const job of dueJobs) {
            try {
              await env.AGENT_JOBS_QUEUE.send(job);
            } catch (error) {
              // Leave the claimed job leased. Reconciliation safely recovers it
              // after lease expiry; never execute it concurrently as a fallback.
              console.error("[worker-scheduled] Queue dispatch failed:", {
                jobId: job.id,
                error: error instanceof Error ? error.message : "Unknown error",
              });
            }
          }
        } catch (error) {
          console.error("[worker-scheduled] Scheduled execution failed:", error);
        }
      })()
    );
  },
} satisfies ExportedHandler<CloudflareBindings>;
